{
  "technical_and_design_decisions": [
    "Baseline JDK: Java 17, consistent with the Spring Framework 6.0 requirement stated in the specification; the increment builds on the existing Spring XD codebase.",
    "U1: The Receptor client is implemented as a standalone Java library with Jackson-based JSON mapping of the Diego Receptor domain model (DesiredLRP, ActualLRP, Task), an HTTP transport layer with typed exception mapping, and is then wired into XD as the integration point to the Diego runtime.",
    "U2: Decoupling is achieved by introducing definition-repository interfaces that manage only stream/job definitions, moving all module-deployment responsibilities to a dedicated deployment service layer; existing persistence mechanisms are reused where possible.",
    "U3: The pluggable runtime SPI follows a deployer-style contract (deploy/undeploy/status/scale) with implementations discovered via Java ServiceLoader / Spring auto-configuration and selected through external configuration per deployment target (CF, on-prem, Mesos); the CF implementation delegates to the U1 Receptor client.",
    "U4: Stream definitions and runtime metadata are persisted in a relational database via Spring JDBC/JPA with Flyway-managed schema migrations; on container restart, persisted metadata drives reestablishment of streaming pipelines.",
    "U6: Spark/Spark Streaming support is delivered as XD modules with isolated classloading for the Spark runtime, aligned with the latest XD stream DSL and Spark APIs.",
    "U8: Each import parameter becomes a first-class, validated module option that is mapped internally to command arguments; the pass-through --args option is deprecated with a documented migration path.",
    "Documentation (U5, U7, and developer docs for U3/U8) is written in the project's existing Asciidoc-based reference documentation format, with examples verified by execution.",
    "Testing approach: JUnit-based unit tests plus integration tests; in-memory H2 for repository tests; local Diego/Receptor and Spark environments for runtime integration tests."
  ],
  "assumptions": [
    "I am the sole developer performing all analysis, design, coding, testing, and documentation; all estimates are effort in work-hours, not elapsed calendar duration.",
    "The existing Spring XD codebase, build system, and CI infrastructure are available and functional, and I have moderate familiarity with the codebase.",
    "A Diego/Receptor test environment (e.g., a local CF/Diego deployment) and a local Spark/Spark Streaming cluster are available for integration testing without extra setup effort beyond what is estimated.",
    "The Receptor API (Diego) and the Spark/Spark Streaming APIs are documented and stable during the increment; the referenced receptor-client repository serves as a design reference only.",
    "Estimates include requirements analysis, design, implementation, unit/integration testing, and documentation within each activity, plus one cross-cutting integration and release activity; they exclude project management, meetings, production deployment, and post-release maintenance.",
    "For U8, 'Import Options' refers to the XD Sqoop-style import job options and the pass-through '--args' option; parameterization covers all options previously expressible only via --args.",
    "For U6, 'latest specs' means the Spark/Spark Streaming versions compatible with the XD release under development; no broader upgrade of XD itself is required.",
    "One work-hour equals one hour of productive engineering effort.",
    "Defect fixing discovered within the increment is included in each activity's estimate; no separate hardening phase is planned beyond the cross-cutting integration testing activity."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Design Receptor Java client API and domain model",
      "activity_description": "Analyze the Diego Receptor API (DesiredLRP, ActualLRP, Task, Cell endpoints) and design the Java client interface, domain model classes, and configuration model (U1).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Implement Receptor client HTTP core",
      "activity_description": "Implement the HTTP/REST transport layer of the Receptor client including JSON serialization (Jackson), authentication, connection configuration, and error/exception mapping (U1).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement Receptor API operations",
      "activity_description": "Implement the Receptor API operations for managing DesiredLRPs, ActualLRPs, and Tasks as typed Java methods on the client (U1).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A4",
      "activity_name": "Write Receptor client tests",
      "activity_description": "Write unit tests and integration tests for the Receptor client against a local Diego/Receptor test environment (U1).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A5",
      "activity_name": "Integrate Receptor client into XD",
      "activity_description": "Wire the client into the XD runtime so Diego interactions go through Receptor API calls, adapting existing XD code accordingly (U1).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "Design repository separation for streams and jobs",
      "activity_description": "Analyze the current coupling of stream/job definition repositories with module deployment concerns and design the new separated interfaces and responsibilities (U2).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A7",
      "activity_name": "Refactor stream definition repository",
      "activity_description": "Refactor the stream definition repository to remove deployment concerns, moving those responsibilities to the deployment service layer (U2).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A8",
      "activity_name": "Refactor job definition repository",
      "activity_description": "Refactor the job definition repository analogously, decoupling definition persistence from module deployment concerns (U2).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A9",
      "activity_name": "Update dependent code and regression tests for refactoring",
      "activity_description": "Adapt all callers of the refactored repositories, update and migrate unit/integration tests, and regression-test stream and job lifecycle operations (U2).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A10",
      "activity_name": "Design pluggable runtime SPI contracts",
      "activity_description": "Define the SPI interfaces and contracts abstracting runtime operations (deploy, undeploy, status, scale) across deployment targets such as CF, on-prem, and Mesos (U3).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A11",
      "activity_name": "Implement SPI core and runtime selection mechanism",
      "activity_description": "Implement the SPI core, implementation discovery (ServiceLoader / Spring auto-configuration), and configuration-based selection of the runtime implementation per deployment target (U3).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A12",
      "activity_name": "Implement reference runtime SPI implementations",
      "activity_description": "Provide a default (local/on-prem) SPI implementation and a Cloud Foundry implementation using the Receptor client from U1; define extension points for other targets such as Mesos (U3).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A13",
      "activity_name": "SPI tests and developer documentation",
      "activity_description": "Write tests validating SPI selection and behavior, and developer documentation describing how to add new runtime implementations (U3).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A14",
      "activity_name": "Design stream persistence schema",
      "activity_description": "Design the relational schema and repository API for persisting stream definitions and the runtime metadata needed for failure recovery (U4).",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A15",
      "activity_name": "Implement persistent stream repository",
      "activity_description": "Implement the persistent repository for streams using Spring JDBC/JPA, including Flyway schema migration scripts (U4).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A16",
      "activity_name": "Implement streaming pipeline recovery logic",
      "activity_description": "Implement the logic that leverages persisted metadata to reestablish streaming pipelines after XD container failure or restart (U4).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A17",
      "activity_name": "Failure and recovery testing",
      "activity_description": "Write tests simulating failure and restart scenarios to validate correct reestablishment of streaming pipelines from persisted metadata (U4).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A18",
      "activity_name": "Document escape-quote handling for Sqoop jobs",
      "activity_description": "Extend the Sqoop job documentation explaining that users must double-escape (e.g., \\\\\\\\N) instead of sending quoted values ('\\N') so jobs submit successfully; verify the documented behavior (U5).",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A19",
      "activity_name": "Design XD and Spark/Spark Streaming integration",
      "activity_description": "Analyze the latest XD and Spark/Spark Streaming APIs and design how Spark streaming modules plug into XD streams, covering module contract, classloading, and configuration (U6).",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A20",
      "activity_name": "Implement Spark Streaming module support",
      "activity_description": "Implement support for creating XD streaming pipelines backed by Spark/Spark Streaming, including module implementation and runtime wiring (U6).",
      "most_likely_effort": 60
    },
    {
      "activity_id": "A21",
      "activity_name": "Spark integration tests and sample pipelines",
      "activity_description": "Write integration tests and sample streaming pipelines demonstrating XD with Spark/Spark Streaming capabilities (U6).",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A22",
      "activity_name": "Document nesting batch jobs and workflows",
      "activity_description": "Write reference documentation with verified examples showing how to nest batch jobs and composed workflows in XD for end users (U7).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A23",
      "activity_name": "Analyze current import options and --args handling",
      "activity_description": "Analyze the existing import job option handling and all current uses of the pass-through --args option (U8).",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A24",
      "activity_name": "Implement parameterized import options",
      "activity_description": "Add first-class, validated options for all import parameters, map them internally to command arguments, and deprecate the --args option (U8).",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A25",
      "activity_name": "Tests and documentation for parameterized import options",
      "activity_description": "Update tests and user documentation for the new import options and verify the backward-compatible migration path for existing --args usage (U8).",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A26",
      "activity_name": "Overall integration testing and release preparation",
      "activity_description": "Perform end-to-end integration testing across the whole increment, update build configuration, and prepare release artifacts (cross-cutting).",
      "most_likely_effort": 32
    }
  ],
  "reported_total": {
    "most_likely_effort": 678
  }
}

